const data = $json;

const requiredFields = [
  "Article Title",
  "Article Content",
  "Category",
  "Author Name",
  "Source",
  "Update Type",
  "Last Updated"
];

const missingFields = requiredFields.filter(
  field =>
    data[field] === undefined ||
    data[field] === null ||
    data[field] === ""
);

return {
  json: {
    ...data,
    data_valid: missingFields.length === 0,
    missing_fields: missingFields
  }
};

