const data = $json;

let result = data.output;

if (typeof result === "string") {
  result = result
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  result = JSON.parse(result);
}

return {
  json: {
    ...data,
    ...result
  }
};

